BEGIN;SET LOCAL statement_timeout='20s';SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','f10bd630-6e35-4513-a9b3-4908d1b00c3c',true);
DO $test$
DECLARE org uuid:='85acbac0-e8b4-434c-a22b-3ec13b55e1a7';party uuid:='d86a111c-d392-4f09-adc1-13f9e72a1c53';p jsonb;r jsonb;salary uuid;loan uuid;le uuid;se uuid;op uuid;reversal uuid;eid uuid;before_cash numeric;err text;fid uuid;second_id uuid;second_event uuid;
BEGIN
 select coalesce(sum(current_balance),0)into before_cash from liquidity_accounts where organization_id=org;
 p:=jsonb_build_object('organization_id',org,'request_id',gen_random_uuid(),'kind','EMPLOYEE_ADVANCE','mode','OPENING','side','RECEIVABLE','counterparty_id',party,'entity_id',null,'account_id',null,'category','O_AR_EMPLOYEE','description','QA employee phase3 rollback','reference','QA-P3','date','2026-10-15','currency','SAR','exchange_rate',1,'principal',100,'schedule',jsonb_build_array(jsonb_build_object('amount',100,'due_date','2026-11-01')));
 r:=create_debt_contract(p);le:=(r->>'eventId')::uuid;perform approve_financial_event(le,'QA approval');perform post_debt_contract((r->>'id')::uuid);select id into loan from financial_event_obligations where event_id=le;
 p:=p||jsonb_build_object('request_id',gen_random_uuid(),'kind','OPENING','side','PAYABLE','category','O_AP_EMPLOYEE','description','QA salary payable rollback','principal',300,'schedule',jsonb_build_array(jsonb_build_object('amount',300,'due_date','2026-11-01')));
 r:=create_debt_contract(p);se:=(r->>'eventId')::uuid;perform approve_financial_event(se,'QA approval');perform post_debt_contract((r->>'id')::uuid);select id into salary from financial_event_obligations where event_id=se;
 p:=jsonb_build_object('organization_id',org,'request_id',gen_random_uuid(),'kind','DEDUCT','installment_id',loan,'salary_obligation_id',salary,'amount',40,'date','2026-10-15','payroll_reference','QA-2026-10','reason','QA payroll deduction');
 r:=prepare_debt_payroll(p);op:=(r->>'id')::uuid;eid:=(r->>'eventId')::uuid;
 if(prepare_debt_payroll(p)->>'id')::uuid<>op then raise exception 'PAYROLL_REPLAY_NOT_SAFE';end if;
 begin perform prepare_debt_payroll(p||jsonb_build_object('request_id',gen_random_uuid()));err:='NOT_BLOCKED';exception when others then err:=SQLERRM;end;if err<>'PAYROLL_PERIOD_ALREADY_RECORDED'then raise exception 'PAYROLL_DUPLICATE_PERIOD:%',err;end if;
 r:=prepare_debt_payroll(p||jsonb_build_object('request_id',gen_random_uuid(),'amount',70,'payroll_reference','QA-SECOND'));second_id:=(r->>'id')::uuid;second_event:=(r->>'eventId')::uuid;perform approve_financial_event(second_event,'QA second request');
 begin perform post_debt_payroll(op);err:='NOT_BLOCKED';exception when others then err:=SQLERRM;end;if err<>'VALID_APPROVAL_REQUIRED'then raise exception 'PAYROLL_APPROVAL_NOT_ENFORCED:%',err;end if;
 begin perform transition_financial_event(eid,'ACTUAL','Direct bypass attempt');err:='NOT_BLOCKED';exception when others then err:=SQLERRM;end;if err='NOT_BLOCKED'then raise exception 'PAYROLL_SOURCE_BYPASSED';end if;
 perform approve_financial_event(eid,'QA payroll approval');perform post_debt_payroll(op);perform post_debt_payroll(op);
 begin perform post_debt_payroll(second_id);err:='NOT_BLOCKED';exception when others then err:=SQLERRM;end;if err<>'PAYROLL_EXCEEDS_BALANCE'then raise exception 'PAYROLL_STALE_BALANCE_NOT_GUARDED:%',err;end if;perform cancel_debt_payroll(second_id,'QA cancel stale request');
 if(select outstanding_base_amount from financial_event_obligation_balances where obligation_id=loan)<>60 or(select outstanding_base_amount from financial_event_obligation_balances where obligation_id=salary)<>260 or(select count(*)from financial_event_obligation_allocations where application_event_id=eid)<>2 then raise exception 'PAYROLL_BALANCES_INVALID';end if;
 if(select coalesce(sum(current_balance),0)from liquidity_accounts where organization_id=org)<>before_cash or exists(select 1 from liquidity_settlements where financial_event_id=eid)then raise exception 'PAYROLL_CHANGED_CASH';end if;
 if(select settled_amount from liquidity_flows where source_module='DEBT_CONTRACTS'and source_record_id=loan)<>40 then raise exception 'PAYROLL_FORECAST_NOT_REDUCED';end if;
 begin perform prepare_debt_payroll(p||jsonb_build_object('request_id',gen_random_uuid(),'amount',70,'payroll_reference','QA-EXCESS'));err:='NOT_BLOCKED';exception when others then err:=SQLERRM;end;if err<>'PAYROLL_EXCEEDS_BALANCE'then raise exception 'PAYROLL_OVERPAYMENT_NOT_BLOCKED:%',err;end if;
 p:=jsonb_build_object('organization_id',org,'request_id',gen_random_uuid(),'kind','REVERSE','target_id',op,'date','2026-10-15','reason','QA reverse payroll');r:=prepare_debt_payroll(p);reversal:=(r->>'id')::uuid;if(prepare_debt_payroll(p)->>'id')::uuid<>reversal then raise exception 'PAYROLL_REVERSE_REPLAY_INVALID';end if;perform approve_financial_event((r->>'eventId')::uuid,'QA reverse approval');perform post_debt_payroll(reversal);perform post_debt_payroll(reversal);
 if(select outstanding_base_amount from financial_event_obligation_balances where obligation_id=loan)<>100 or(select outstanding_base_amount from financial_event_obligation_balances where obligation_id=salary)<>300 or(select settled_amount from liquidity_flows where source_module='DEBT_CONTRACTS'and source_record_id=loan)<>0 then raise exception 'PAYROLL_REVERSAL_NOT_RECONCILED';end if;
 perform set_config('qa.phase3_payroll',jsonb_build_object('approval_required',true,'duplicate_period_blocked',true,'stale_execution_blocked',true,'replay_safe',true,'receivable_and_payable_reduced',true,'cash_unchanged',true,'forecast_reconciled',true,'reversal_restored',true,'rollback',true)::text,true);
END $test$;
SELECT current_setting('qa.phase3_payroll')::jsonb result;ROLLBACK;
